before:
body > .platform-leaf-layer::before,body > .platform-leaf-layer::after{content:"";position:absolute;top:0;width:38%;max-width:420px;height:22px;pointer-events:none;background:url("platform-assets/tree-canopy.svg") left top/100% 22px no-repeat;opacity:.62}
body > .platform-leaf-layer::before{left:0}
body > .platform-leaf-layer::after{right:0;background-position:right top;opacity:.42}

after:
/* Only the canopy adopts pixel art. The added header border reserves space
   without changing text, game widths, or the approved leaf motion rules. */
body > header{border-top:88px solid #fafbf7}
body > .platform-leaf-layer::before{content:"";position:absolute;top:0;left:0;width:100%;height:88px;pointer-events:none;background:url("platform-assets/tree-canopy-pixel.svg") center top/960px 88px repeat-x;image-rendering:pixelated;opacity:.82}
@media(max-width:760px){
 body > header{border-top-width:64px}
 body > .platform-leaf-layer::before{height:64px;background-size:720px 66px}
}
